import 'package:flutter/material.dart';
import '../services/auth_service.dart';
import '../models/models.dart';
import 'home_screen.dart';
class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginState();}
class _LoginState extends State<LoginScreen>{final u=TextEditingController(),p=TextEditingController();bool loading=false;String? error;final auth=AuthService();
 Future<void> login()async{setState((){loading=true;error=null;});try{final user=await auth.signIn(u.text,p.text);if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomeScreen(user:user)));}catch(e){setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> bootstrap()async{setState(()=>loading=true);try{await auth.bootstrapAdmin();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم تجهيز المسؤول الافتراضي. استخدم admin / 123456')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[const Icon(Icons.inventory_2_rounded,size:70,color:Color(0xff146c94)),const SizedBox(height:12),Text('طلبات مناديب الجوديا',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:8),const Text('سجّل الدخول لإدارة الطلبات',textAlign:TextAlign.center),const SizedBox(height:24),TextField(controller:u,decoration:const InputDecoration(labelText:'اسم المستخدم',prefixIcon:Icon(Icons.person))),const SizedBox(height:12),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'كلمة المرور',prefixIcon:Icon(Icons.lock))),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:20),SizedBox(width:double.infinity,child:FilledButton(onPressed:loading?null:login,child:loading?const CircularProgressIndicator():const Text('دخول'))),const SizedBox(height:8),TextButton(onPressed:loading?null:bootstrap,child:const Text('إنشاء المسؤول الافتراضي admin'))]))))));}
}
